// Generates CodeRabbit config fragments from skills, so custom pre-merge checks get the
// exact rule text. The skills stay the source of truth; never edit the generated files.
//
//   node scripts/generate-coderabbit-checks.mjs
//
// Repos include a fragment from their .coderabbit.config.ts with:
//   includeRemote({ repo: "coderabbit-demo/sharechat-ai-context", path: "coderabbit/<name>.ts", ref: "main" })

import { readFileSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const root = join(dirname(fileURLToPath(import.meta.url)), "..")
const MAX_INSTRUCTIONS = 10_000 // CodeRabbit limit per custom check

const CHECKS = [
	{
		output: "coderabbit/mobile-api-compatibility.ts",
		name: "Mobile API Compatibility Guidelines",
		mode: "error",
		skillDir: "plugins/api-compatibility/skills/mobile-api-compatibility",
		files: ["SKILL.md", "references/compatibility-rules.md"],
		intro: `Evaluate the change against the mobile-api-compatibility skill from sharechat-ai-context.
The full text of the skill is included below; it is the complete set of rules for this check.

- Fail if the change violates any rule below. For each violation, quote the rule, name the file it
  comes from (as labelled below), and point to the line in this PR that violates it.
- Consider the effect of the change, not only the lines edited: a dependency, configuration, or library
  change can violate a rule about API responses without touching the API code itself.
- In the result, list which skill files were applied.
- Pass if no rule is violated.`,
	},
]

function stripFrontmatter(text) {
	return text.replace(/^---\n[\s\S]*?\n---\n+/, "")
}

function templateLiteral(text) {
	return "`" + text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${") + "`"
}

for (const check of CHECKS) {
	const sections = check.files.map(file => {
		const body = stripFrontmatter(readFileSync(join(root, check.skillDir, file), "utf8")).trim()
		return `===== ${check.skillDir}/${file} =====\n${body}`
	})
	const instructions = [check.intro, ...sections].join("\n\n")
	if (instructions.length > MAX_INSTRUCTIONS) {
		throw new Error(`${check.name}: instructions are ${instructions.length} chars (max ${MAX_INSTRUCTIONS})`)
	}

	const source = `// GENERATED by scripts/generate-coderabbit-checks.mjs from ${check.skillDir}.
// Do not edit by hand; change the skill and re-run the script.
import type { CodeRabbitConfig } from "@coderabbitai/config"

export default {
	reviews: {
		pre_merge_checks: {
			custom_checks: [
				{
					mode: ${JSON.stringify(check.mode)},
					name: ${JSON.stringify(check.name)},
					instructions: ${templateLiteral(instructions)},
				},
			],
		},
	},
} satisfies CodeRabbitConfig
`
	writeFileSync(join(root, check.output), source)
	console.log(`wrote ${check.output} (${instructions.length} chars)`)
}
